💡 Tip 4: Audit 정보로 변경 이력 조회
// Repository
interface UserRepository : MongoRepository<User, String> {
// 특정 사용자가 생성한 모든 문서 조회
fun findByCreatedBy(createdBy: String): List<User>
// 특정 기간에 생성된 문서 조회
fun findByCreatedAtBetween(start: LocalDateTime, end: LocalDateTime): List<User>
// 최근 수정된 문서 조회
fun findTop10ByOrderByUpdatedAtDesc(): List<User>
}
// Service
@Service
class AuditService(
private val userRepository: UserRepository
) {
// 특정 사용자의 활동 내역 조회
fun getUserActivity(userId: String): UserActivityReport {
val createdDocuments = userRepository.findByCreatedBy(userId)
val recentUpdates = userRepository.findTop10ByOrderByUpdatedAtDesc()
.filter { it.updatedBy == userId }
return UserActivityReport(
totalCreated = createdDocuments.size,
recentUpdates = recentUpdates
)
}
}
